const show=()=>{const state=+stateGb.value*1024,delta=+deltaMb.value,sst=+sstMb.value,n=+snapshotEvery.value,b=+failureBatch.value;const lastBase=Math.floor(b/n)*n;const replayBatches=b-lastBase;const snapshotFg=b*sst;const changeFg=b*delta;const snapshotBg=Math.floor(b/n)*state;world.textContent='Through batch '+b+'
Traditional foreground changed-SST upload: '+(snapshotFg/1024).toFixed(1)+' GB
Changelog foreground upload: '+(changeFg/1024).toFixed(1)+' GB
Toy background base snapshots: '+(snapshotBg/1024).toFixed(1)+' GB
Latest completed base: batch '+lastBase+'
Deltas to replay: '+replayBatches+' ('+(replayBatches*delta/1024).toFixed(1)+' GB)

Hot-path winner in this toy: '+(changeFg<snapshotFg?'CHANGELOG':'INCREMENTAL SNAPSHOT')+'
A background snapshot bounds replay; it does not make durability free.'};[stateGb,deltaMb,sstMb,snapshotEvery,failureBatch].forEach(e=>e.oninput=show);show();
function drawMechanism(){const b=+failureBatch.value,n=+snapshotEvery.value,base=Math.floor(b/n)*n,delta=+deltaMb.value,sst=+sstMb.value,max=Math.max(b*delta,b*sst);visualField.innerHTML='<p>Batch number. Double border = completed base snapshot; gold fill = delta needed after the latest base.</p><div class="batch-strip">'+Array.from({length:b+1},(_,i)=>'<span class="'+(i===base?'base ': '')+(i>base?'replay':'')+'">'+i+(i===base?'<br>BASE':'')+'</span>').join('')+'</div><p>Crash after '+b+' → restore base '+base+' → replay '+(b-base)+' deltas ('+((b-base)*delta/1024).toFixed(1)+' GB).</p><p>Foreground upload through batch '+b+' (both bars use '+(max/1024).toFixed(1)+' GB full scale):</p><p>Changed SST: '+(b*sst/1024).toFixed(1)+' GB</p><div class="upload-bar"><span style="width:'+100*b*sst/max+'%"></span></div><p>Changelog: '+(b*delta/1024).toFixed(1)+' GB</p><div class="upload-bar"><span style="width:'+100*b*delta/max+'%"></span></div><p>Move failure one batch past a base: replay starts growing again. The toy assumes each scheduled base has completed; real snapshots can lag.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[stateGb,deltaMb,sstMb,snapshotEvery,failureBatch].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const n=+writers.value,d=+decrement.value,q=+quantity.value;if(q<n*d){world.textContent='Reservation demand exceeds available stock. The all-writers-eventually-succeed toy no longer applies. Reread and reject reservations that cannot be fulfilled; never clamp a successful sale to zero. See the version-gate visual.';return;}const unguarded=Math.max(0,q-d);const guarded=Math.max(0,q-n*d);const attempts=n*(n+1)/2;world.textContent=n+' writers all read quantity '+q+' at version 7.

Blind read-modify-write final quantity: '+unguarded+'
Silent lost reservations: '+Math.max(0,n-1)+'

Versioned conditional-write final quantity: '+guarded+'
Successful writes: '+n+'
Conflicts before eventual success: '+(attempts-n)+'
Total conditional attempts in synchronized rounds: '+attempts+'

The guarded value is correct only if every reservation remains valid when recomputed.'};[writers,decrement,quantity].forEach(e=>e.oninput=show);show();
function drawMechanism(){const n=+writers.value,d=+decrement.value,q=+quantity.value,valid=q>=n*d;visualField.innerHTML='<p>'+n+' workers read <strong>quantity '+q+', version 7</strong>. Each wants '+d+' unit(s).</p><div class="write-comparison"><section><h4>Blind overwrite</h4><ol><li>W1 saves '+Math.max(0,q-d)+'.</li><li>W2 saves the same '+Math.max(0,q-d)+'.</li><li>All other writers repeat it.</li></ol><p>Stored: '+Math.max(0,q-d)+'. Earlier reservations vanish.</p></section><section><h4>Version gate</h4><ol><li>W1: version 7 matches → quantity '+Math.max(0,q-d)+', version 8.</li><li>W2: expects 7, sees 8 → REJECT.</li><li>W2 rereads, checks stock, then retries with version 8.</li></ol><p>'+(valid?'After all valid retries: '+(q-n*d)+' units, version '+(7+n)+'.':'Stock cannot fulfill every request. A real retry must reject reservations once stock is insufficient; do not count every writer as successful.')+'</p></section></div><p>Concurrency control detects a stale calculation. It does not decide whether the recalculated business operation is still allowed.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[writers,decrement,quantity].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const duration=+experimentSec.value,error=+errorPct.value,threshold=+thresholdPct.value,period=+periodSec.value,n=+periods.value,recovery=+recoverySec.value;const breaches=error>threshold;const active=breaches?Math.min(duration,n*period+recovery):duration;world.textContent='Hypothesis boundary: error rate ≤ '+threshold.toFixed(1)+'%
Observed synthetic rate: '+error.toFixed(1)+'%
Guardrail: '+(breaches?'TRIGGERS':'DOES NOT TRIGGER')+'
Modeled fault + recovery window: '+active+' s
Modeled exposure: '+(error*active).toFixed(0)+' %-seconds

'+(breaches?'The alarm limits duration after detection; it does not erase impact.':'No alarm means the experiment runs to its planned end. Check whether the metric can miss harm.')};[experimentSec,errorPct,thresholdPct,periodSec,periods,recoverySec].forEach(e=>e.oninput=show);show();
function drawMechanism(){const duration=+experimentSec.value,error=+errorPct.value,threshold=+thresholdPct.value,detect=+periodSec.value*+periods.value,recovery=+recoverySec.value,breach=error>threshold,active=breach?Math.min(duration,detect+recovery):duration,observe=Math.min(active,detect),tail=active-observe;visualField.innerHTML='<p>Fixed-rate toy: '+error.toFixed(1)+'% errors '+(breach?'exceeds':'does not exceed')+' '+threshold.toFixed(1)+'% threshold.</p><div class="fault-timeline" aria-label="Modeled exposure '+active+' seconds out of '+duration+' planned seconds"><span style="width:'+100*(breach?observe:active)/duration+'%"></span>'+(breach?'<span class="recover" style="width:'+100*tail/duration+'%"></span>':'')+'<span class="quiet" style="width:'+100*(duration-active)/duration+'%"></span></div><p>0 s → '+(breach?'detection after '+detect+' s → stop/recovery '+recovery+' s':'no stop alarm')+' → planned end '+duration+' s.</p><p>Modeled exposure ends at <strong>'+active+' s</strong>. '+(breach&&detect>=duration?'The planned end arrives before sufficient breaching periods accumulate.':breach?'The alarm is a delayed intervention, not a shield around the experiment.':'The experiment continues to its planned end; check whether the metric misses customer harm.')+'</p><p>Blue = observation/fault active; gold = stop/recovery; green = remaining planned time. This toy caps exposure at planned duration; real recovery can continue afterward.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[experimentSec,errorPct,thresholdPct,periodSec,periods,recoverySec].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const trusted=trustedServer.checked;const external=trusted?openWorld.checked:true;const destructiveEffective=trusted?destructive.checked:true;const trifecta=privateData.checked&&untrustedInput.checked&&external;let decision=trifecta?'BLOCK / require path redesign':destructiveEffective?'REQUIRE EXPLICIT APPROVAL':'ALLOW UNDER LEAST-PRIVILEGE POLICY';const retry=idempotencyKey.checked||(trusted&&idempotent.checked);world.textContent='Annotation trust: '+(trusted?'accepted as routing evidence':'UNTRUSTED — pessimistic defaults')+'
External communication potential: '+(external?'YES':'no')+'
Private + untrusted + external combination: '+(trifecta?'PRESENT':'not present')+'
Harness decision: '+decision+'
Automatic retry: '+(retry?'PERMITTED BY THIS TOY POLICY':'NOT PERMITTED')+'

Hints affect UX. Capabilities, sandboxing, egress policy, approvals, and ledgers enforce safety.'};[trustedServer,privateData,untrustedInput,openWorld,destructive,idempotent,idempotencyKey].forEach(e=>e.oninput=show);show();
function drawMechanism(){const trusted=trustedServer.checked,external=trusted?openWorld.checked:true,combination=privateData.checked&&untrustedInput.checked&&external;visualField.innerHTML='<ol class="risk-route"><li class="'+(untrustedInput.checked?'open':'closed')+'">1. Untrusted instructions: '+(untrustedInput.checked?'present':'absent — route broken')+'</li><li class="'+(privateData.checked?'open':'closed')+'">2. Private data reachable: '+(privateData.checked?'yes':'no — route broken')+'</li><li class="'+(external?'open':'closed')+'">3. External communication potential: '+(external?'yes':'no in this trusted description')+'</li></ol><p><strong>'+ (combination?'All three connect → block or redesign this path.':'At least one condition is absent → this particular combination is broken.')+'</strong></p><p>Annotation origin: '+(trusted?'trusted release; hints can route review':'untrusted; external and destructive effects assumed possible')+'. Hints do not enforce any of these gates.</p><table><tr><th>Claim</th><th>Actual control needed</th></tr><tr><td>Read-only</td><td>Filesystem/service permissions</td></tr><tr><td>No outside contact</td><td>Egress allowlist</td></tr><tr><td>Safe retry</td><td>'+(idempotencyKey.checked?'Durable key/ledger selected':'Verify semantics or add a durable ledger')+'</td></tr></table>';}
const syncMechanism=()=>{show();drawMechanism();};[trustedServer,privateData,untrustedInput,openWorld,destructive,idempotent,idempotencyKey].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const cap=+capacityMah.value,load=+loadUa.value/1000,usable=+usablePct.value/100;const hours=cap*usable/load;world.textContent='Nominal capacity: '+cap.toFixed(1)+' mAh
Average load: '+(load*1000).toFixed(0)+' μA
Usable energy fraction: '+(usable*100).toFixed(0)+'%
Toy runtime: '+hours.toFixed(1)+' hours ('+(hours/24).toFixed(2)+' days)

The paper reports 1.84 V peak open circuit and swine prototypes. This calculator does not predict in-vivo or human performance.'};[capacityMah,loadUa,usablePct].forEach(e=>e.oninput=show);show();
function drawMechanism(){const nominal=+capacityMah.value,usable=nominal*+usablePct.value/100,load=+loadUa.value/1000,hours=usable/load,axis=Math.max(24,Math.ceil(hours/24)*24),endX=45+270*hours/axis,startY=160-120*usable/5;visualField.innerHTML='<p>Nominal '+nominal.toFixed(1)+' mAh → reserve/margin '+(nominal-usable).toFixed(2)+' mAh → usable '+usable.toFixed(2)+' mAh.</p><svg viewBox="0 0 365 215" role="img" aria-label="Charge drains from '+usable.toFixed(2)+' milliamp hours to zero in '+hours.toFixed(1)+' hours"><path d="M45 25 V160 H325" fill="none" stroke="#a2c0c9"/><text x="4" y="41" font-size="12">5 mAh</text><text x="20" y="165" font-size="12">0</text><path d="M45 '+startY+' L'+endX+' 160" stroke="#f0c88c" stroke-width="3" fill="none"/><circle cx="'+endX+'" cy="160" r="4" fill="#f0c88c"/><text x="45" y="182" font-size="13">0 h</text><text x="285" y="182" font-size="13">'+axis+' h</text><text x="75" y="205" font-size="14">Drain: '+load.toFixed(3)+' mA</text></svg><p>Zero-charge crossing: <strong>'+hours.toFixed(1)+' hours</strong>. Doubling current doubles the slope and halves runtime.</p><p>One charge estimate does not establish loaded voltage, in-vivo lifetime, safe resorption, or human treatment readiness. This is not a simulated biological battery.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[capacityMah,loadUa,usablePct].forEach(e=>e.oninput=syncMechanism);drawMechanism();
